"use client"

import * as React from "react"

import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { AppShell } from "@/components/shell/app-shell"
import { MockupShell } from "@/components/shell/mockup-shell"
import {
  PersonasIndex,
  type PreviewState,
} from "@/components/mockups/personas-depth/personas-index"
import { VoiceLibrary } from "@/components/mockups/personas-depth/voice-library"

/**
 * DES-117 — the personas surface in the shared product chrome. Personas and
 * Voice Library are separate pages in the product's sidebar, so they are two
 * views of this one route, switched from the nav — no extra tabs on the page.
 * The state toggle lives in the workspace bar above the design.
 */
export default function PersonasDepthPage() {
  const [previewState, setPreviewState] = React.useState<PreviewState>("data")
  const [view, setView] = React.useState<"Personas" | "Voice Library">(
    "Personas",
  )

  return (
    <MockupShell
      eyebrow="Page depth"
      title="Personas"
      actions={
        <>
          <span className="text-xs text-muted-foreground">Preview</span>
          <ToggleGroup
            type="single"
            variant="outline"
            size="sm"
            value={previewState}
            onValueChange={(value) => {
              if (value) setPreviewState(value as PreviewState)
            }}
          >
            <ToggleGroupItem value="data">Data</ToggleGroupItem>
            <ToggleGroupItem value="loading">Loading</ToggleGroupItem>
            <ToggleGroupItem value="empty">Empty</ToggleGroupItem>
            <ToggleGroupItem value="error">Error</ToggleGroupItem>
          </ToggleGroup>
        </>
      }
    >
      <AppShell
        active={view}
        onNavigate={(title) => {
          if (title === "Personas" || title === "Voice Library") setView(title)
        }}
      >
        {/* Same gutter as the Conversations page, and no page heading for the
            same reason it has none: the sidebar item is already lit and the
            breadcrumb already says Personas, so an <h1> repeats the answer to a
            question nobody asked and costs a row of vertical space above the
            filters. */}
        {/* A flex column with no gap: the column is what lets the empty state's
            own `flex-1` fill the page and centre itself, and no gap keeps the
            filter row at the same y as the Conversations page. It was `block`
            for a moment, which made `flex-1` inert and left the empty state
            pinned to the top above 700px of nothing. */}
        <div className="flex flex-1 flex-col p-3 lg:p-4">
          {view === "Personas" ? (
            <PersonasIndex state={previewState} />
          ) : (
            <VoiceLibrary state={previewState} />
          )}
        </div>
      </AppShell>
    </MockupShell>
  )
}

"use client"

import {
  Alert02Icon,
  AudioWave01Icon,
  CheckmarkCircle02Icon,
  Delete02Icon,
  Edit02Icon,
  MoreHorizontalIcon,
  PlayIcon,
  Refresh01Icon,
  Search01Icon,
  StarIcon,
  StopIcon,
  Target02Icon,
  UserAdd01Icon,
  UserMultipleIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/* Index toolbar and rows. */
export const SearchIcon = icon(Search01Icon, "SearchIcon")
export const AddPersonaIcon = icon(UserAdd01Icon, "AddPersonaIcon")
export const EditIcon = icon(Edit02Icon, "EditIcon")
export const DeleteIcon = icon(Delete02Icon, "DeleteIcon")
export const RowMenuIcon = icon(MoreHorizontalIcon, "RowMenuIcon")
export const MakeDefaultIcon = icon(StarIcon, "MakeDefaultIcon")
export const ScenariosIcon = icon(Target02Icon, "ScenariosIcon")

/* Voice previews, everywhere a voice can be heard. */
export const PlayPreviewIcon = icon(PlayIcon, "PlayPreviewIcon")
export const StopPreviewIcon = icon(StopIcon, "StopPreviewIcon")
export const VoiceWaveIcon = icon(AudioWave01Icon, "VoiceWaveIcon")
export const SelectedVoiceIcon = icon(
  CheckmarkCircle02Icon,
  "SelectedVoiceIcon",
)

/* Edge states. */
export const LoadErrorIcon = icon(Alert02Icon, "LoadErrorIcon")
export const RetryIcon = icon(Refresh01Icon, "RetryIcon")
export const NoPersonasIcon = icon(UserMultipleIcon, "NoPersonasIcon")

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Field, FieldDescription, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { ScrollArea } from "@/components/ui/scroll-area"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Separator } from "@/components/ui/separator"
import { Slider } from "@/components/ui/slider"
import { Switch } from "@/components/ui/switch"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Textarea } from "@/components/ui/textarea"
import {
  GENDERS,
  LANGUAGES,
  type Persona,
  type PersonaGender,
  type PersonaLanguage,
} from "@/lib/mockups/personas-depth-data"
import { VoicePicker } from "@/components/mockups/personas-depth/voice-picker"

export type PersonaDraft = {
  name: string
  language: PersonaLanguage
  gender: PersonaGender
  voiceId: string
  prompt: string
}

/* The product's actual Arabic defaults — see the platform's
   components/settings/backchannel-settings.tsx. */
const DEFAULT_FILLER_WORDS = ["تمام", "حاضر", "ممتاز", "زين", "نعم"]

/* The product's four ambience options, "Office" first as its default. */
const NOISE_TYPES = ["Office", "City Street", "Crowded Room", "Forest"]

/**
 * Create and edit share one dialog. The current product stacks ten sections
 * into a single narrow scroll (the DIS-17 complaint); here the form is split
 * into three tabs — identity, voice, conversation behavior — with the footer
 * always in reach.
 *
 * The form lives in a child mounted with the dialog content, so every open
 * starts from the persona being edited (or a blank slate) without effects.
 */
export function PersonaDialog({
  open,
  onOpenChange,
  persona,
  onSubmit,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** Present when editing; absent when creating. */
  persona: Persona | null
  onSubmit: (draft: PersonaDraft) => void
}) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-3xl">
        <PersonaForm
          key={persona?.id ?? "new"}
          persona={persona}
          onSubmit={onSubmit}
          onClose={() => onOpenChange(false)}
        />
      </DialogContent>
    </Dialog>
  )
}

function PersonaForm({
  persona,
  onSubmit,
  onClose,
}: {
  persona: Persona | null
  onSubmit: (draft: PersonaDraft) => void
  onClose: () => void
}) {
  const editing = persona !== null

  const [tab, setTab] = React.useState("profile")
  const [name, setName] = React.useState(persona?.name ?? "")
  const [language, setLanguage] = React.useState<PersonaLanguage>(
    persona?.language ?? "Arabic",
  )
  const [gender, setGender] = React.useState<PersonaGender>(
    persona?.gender ?? "Female",
  )
  const [voiceId, setVoiceId] = React.useState(persona?.voiceId ?? "")
  const [prompt, setPrompt] = React.useState(persona?.prompt ?? "")
  const [speed, setSpeed] = React.useState(1)

  /* Conversation behavior — mock-local, not part of the submitted draft. */
  const [backchannel, setBackchannel] = React.useState(true)
  const [fillerWords, setFillerWords] = React.useState(DEFAULT_FILLER_WORDS)
  const [fillerDraft, setFillerDraft] = React.useState("")
  const [fillerFrequency, setFillerFrequency] = React.useState(0.6)
  const [backgroundNoise, setBackgroundNoise] = React.useState(false)
  const [noiseType, setNoiseType] = React.useState("Office")
  const [noiseVolume, setNoiseVolume] = React.useState(0.05)
  const [turnOverride, setTurnOverride] = React.useState(false)
  const [minWait, setMinWait] = React.useState("0.4")
  const [maxWait, setMaxWait] = React.useState("1.2")
  const [timeoutOn, setTimeoutOn] = React.useState(true)
  const [timeoutSeconds, setTimeoutSeconds] = React.useState("8")
  const [timeoutRetries, setTimeoutRetries] = React.useState("2")

  function changeLanguage(next: PersonaLanguage) {
    setLanguage(next)
    setVoiceId("")
  }

  function changeGender(next: PersonaGender) {
    setGender(next)
    setVoiceId("")
  }

  function addFillerWord() {
    const word = fillerDraft.trim()
    if (!word || fillerWords.includes(word)) return
    setFillerWords([...fillerWords, word])
    setFillerDraft("")
  }

  const canSave = name.trim().length > 0 && voiceId !== ""

  return (
    <>
      <DialogHeader>
        <DialogTitle>{editing ? "Edit persona" : "New persona"}</DialogTitle>
        <DialogDescription>
          A persona bundles a voice, a prompt, and conversation behavior for one
          language.
        </DialogDescription>
      </DialogHeader>

      <Tabs value={tab} onValueChange={setTab}>
        <TabsList>
          <TabsTrigger value="profile">Profile</TabsTrigger>
          <TabsTrigger value="voice">Voice</TabsTrigger>
          <TabsTrigger value="conversation">Conversation</TabsTrigger>
        </TabsList>

        {/* ScrollArea instead of overflow-y-auto: the bar is an overlay that
            only shows while scrolling, so no permanent gutter on the right. */}
        <TabsContent value="profile" className="pt-2">
          <ScrollArea className="[&>[data-slot=scroll-area-viewport]]:max-h-140">
            <div className="flex flex-col gap-4 pe-3">
              <Field>
                <FieldLabel htmlFor="persona-name">Name *</FieldLabel>
                <Input
                  id="persona-name"
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                  placeholder="Aisha — Yelo Support"
                />
              </Field>

              <div className="grid gap-4 md:grid-cols-2">
                <Field>
                  <FieldLabel>Language *</FieldLabel>
                  <Select
                    value={language}
                    onValueChange={(value) =>
                      changeLanguage(value as PersonaLanguage)
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {LANGUAGES.map((option) => (
                        <SelectItem key={option} value={option}>
                          {option}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </Field>

                <Field>
                  <FieldLabel>Gender *</FieldLabel>
                  <Select
                    value={gender}
                    onValueChange={(value) =>
                      changeGender(value as PersonaGender)
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {GENDERS.map((option) => (
                        <SelectItem key={option} value={option}>
                          {option}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </Field>
              </div>

              <Field>
                <FieldLabel htmlFor="persona-prompt">Persona prompt</FieldLabel>
                <Textarea
                  id="persona-prompt"
                  rows={5}
                  value={prompt}
                  onChange={(event) => setPrompt(event.target.value)}
                  placeholder="Define the agent's identity, personality, and tone."
                />
              </Field>
            </div>
          </ScrollArea>
        </TabsContent>

        <TabsContent value="voice" className="pt-2">
          <ScrollArea className="[&>[data-slot=scroll-area-viewport]]:max-h-140">
            <div className="flex flex-col gap-4 pe-3">
              <VoicePicker
                language={language}
                gender={gender}
                selectedId={voiceId}
                onSelect={setVoiceId}
              />

              {voiceId ? (
                <Field>
                  <div className="flex items-center justify-between gap-4">
                    <FieldLabel>Voice speed</FieldLabel>
                    <span className="font-mono text-sm text-muted-foreground">
                      {speed.toFixed(2)}×
                    </span>
                  </div>
                  <Slider
                    value={[speed]}
                    onValueChange={([value]) => setSpeed(value)}
                    min={0.8}
                    max={1.2}
                    step={0.05}
                  />
                  <FieldDescription>
                    Follows the voice&apos;s own default until you move it.
                  </FieldDescription>
                </Field>
              ) : null}
            </div>
          </ScrollArea>
        </TabsContent>

        <TabsContent value="conversation" className="pt-2">
          <ScrollArea className="[&>[data-slot=scroll-area-viewport]]:max-h-140">
            <div className="flex flex-col gap-4 pe-3">
              <GroupPanel label="Sound">
                <SettingRow
                  title="Backchannel"
                  description={
                    backchannel
                      ? "Short acknowledgements while the caller speaks."
                      : "The agent stays silent while the caller speaks."
                  }
                  control={
                    <Switch
                      checked={backchannel}
                      onCheckedChange={setBackchannel}
                      aria-label="Toggle backchannel"
                    />
                  }
                >
                  {backchannel ? (
                    <>
                      {/* Outline chips, not secondary — secondary is the same
                        grey as the panel, so the chips disappeared. */}
                      <div className="flex flex-wrap gap-2">
                        {fillerWords.map((word) => (
                          <Button
                            key={word}
                            variant="outline"
                            size="xs"
                            onClick={() =>
                              setFillerWords(
                                fillerWords.filter((other) => other !== word),
                              )
                            }
                            aria-label={`Remove filler word ${word}`}
                          >
                            <span dir="auto">{word}</span> ×
                          </Button>
                        ))}
                      </div>
                      <Input
                        value={fillerDraft}
                        onChange={(event) => setFillerDraft(event.target.value)}
                        onKeyDown={(event) => {
                          if (event.key === "Enter") {
                            event.preventDefault()
                            addFillerWord()
                          }
                        }}
                        placeholder="Add a filler word and press Enter"
                        aria-label="Add filler word"
                      />
                      <SliderRow
                        label="Frequency"
                        readout={`${Math.round(fillerFrequency * 100)}%`}
                      >
                        <Slider
                          value={[fillerFrequency]}
                          onValueChange={([value]) => setFillerFrequency(value)}
                          min={0.05}
                          max={1}
                          step={0.05}
                        />
                      </SliderRow>
                    </>
                  ) : null}
                </SettingRow>

                <Separator />

                <SettingRow
                  title="Background noise"
                  description={
                    backgroundNoise
                      ? "A low ambience bed plays behind the voice."
                      : "Calls play no ambience behind the voice."
                  }
                  control={
                    <Switch
                      checked={backgroundNoise}
                      onCheckedChange={setBackgroundNoise}
                      aria-label="Toggle background noise"
                    />
                  }
                >
                  {backgroundNoise ? (
                    <>
                      <Select value={noiseType} onValueChange={setNoiseType}>
                        <SelectTrigger
                          aria-label="Sound type"
                          className="max-w-56"
                        >
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {NOISE_TYPES.map((option) => (
                            <SelectItem key={option} value={option}>
                              {option}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <SliderRow
                        label="Volume"
                        readout={`${Math.round(noiseVolume * 100)}%`}
                      >
                        <Slider
                          value={[noiseVolume]}
                          onValueChange={([value]) => setNoiseVolume(value)}
                          min={0.05}
                          max={1}
                          step={0.05}
                        />
                      </SliderRow>
                    </>
                  ) : null}
                </SettingRow>
              </GroupPanel>

              <GroupPanel label="Timing">
                <SettingRow
                  title="Turn timing"
                  description={
                    turnOverride
                      ? "Custom waits for this persona."
                      : `Waits follow the organization defaults for ${language}.`
                  }
                  control={
                    <Button
                      variant="outline"
                      size="xs"
                      onClick={() => setTurnOverride(!turnOverride)}
                    >
                      {turnOverride ? "Use global" : "Override"}
                    </Button>
                  }
                >
                  {turnOverride ? (
                    <div className="grid max-w-sm grid-cols-2 gap-3">
                      <Field>
                        <FieldLabel htmlFor="turn-min">Min wait (s)</FieldLabel>
                        <Input
                          id="turn-min"
                          value={minWait}
                          onChange={(event) => setMinWait(event.target.value)}
                          inputMode="decimal"
                        />
                      </Field>
                      <Field>
                        <FieldLabel htmlFor="turn-max">Max wait (s)</FieldLabel>
                        <Input
                          id="turn-max"
                          value={maxWait}
                          onChange={(event) => setMaxWait(event.target.value)}
                          inputMode="decimal"
                        />
                      </Field>
                    </div>
                  ) : null}
                </SettingRow>

                <Separator />

                <SettingRow
                  title="Silence timeout"
                  description={
                    timeoutOn
                      ? "Reprompt when the caller goes quiet."
                      : "The call stays open however long the caller pauses."
                  }
                  control={
                    <Switch
                      checked={timeoutOn}
                      onCheckedChange={setTimeoutOn}
                      aria-label="Toggle silence timeout"
                    />
                  }
                >
                  {timeoutOn ? (
                    <div className="grid max-w-sm grid-cols-2 gap-3">
                      <Field>
                        <FieldLabel htmlFor="timeout-duration">
                          Duration (s)
                        </FieldLabel>
                        <Input
                          id="timeout-duration"
                          value={timeoutSeconds}
                          onChange={(event) =>
                            setTimeoutSeconds(event.target.value)
                          }
                          inputMode="numeric"
                        />
                      </Field>
                      <Field>
                        <FieldLabel htmlFor="timeout-retries">
                          Max retries
                        </FieldLabel>
                        <Input
                          id="timeout-retries"
                          value={timeoutRetries}
                          onChange={(event) =>
                            setTimeoutRetries(event.target.value)
                          }
                          inputMode="numeric"
                        />
                      </Field>
                    </div>
                  ) : null}
                </SettingRow>
              </GroupPanel>
            </div>
          </ScrollArea>
        </TabsContent>
      </Tabs>

      <DialogFooter>
        {!canSave ? (
          <span className="me-auto self-center text-sm text-muted-foreground">
            {name.trim()
              ? "Pick a voice to finish."
              : voiceId
                ? "Name the persona to finish."
                : "A name and a voice are required."}
          </span>
        ) : null}
        <DialogClose asChild>
          <Button variant="outline">Cancel</Button>
        </DialogClose>
        <Button
          disabled={!canSave}
          onClick={() => {
            onSubmit({ name: name.trim(), language, gender, voiceId, prompt })
            onClose()
          }}
        >
          {editing ? "Save changes" : "Create persona"}
        </Button>
      </DialogFooter>
    </>
  )
}

/**
 * Two settings that belong together, on one muted panel with a quiet label.
 */
function GroupPanel({
  label,
  children,
}: {
  label: string
  children: React.ReactNode
}) {
  // Half-strength muted: full-strength matches the Slider track's own token
  // exactly, which made the unfilled track invisible.
  return (
    <section className="flex flex-col gap-4 rounded-lg bg-muted/50 p-4">
      <span className="text-xs font-medium text-muted-foreground">{label}</span>
      {children}
    </section>
  )
}

/**
 * One setting inside a group: title and control on the first line, the
 * one-line status under them, expanded fields below. The status copy changes
 * with the switch, so a collapsed setting still says what "off" means.
 */
function SettingRow({
  title,
  description,
  control,
  children,
}: {
  title: string
  description: string
  control: React.ReactNode
  children?: React.ReactNode
}) {
  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-col gap-0.5">
        <div className="flex items-center justify-between gap-4">
          <h3 className="text-sm font-medium">{title}</h3>
          {control}
        </div>
        <p className="text-sm text-muted-foreground">{description}</p>
      </div>
      {children ? <div className="flex flex-col gap-3">{children}</div> : null}
    </div>
  )
}

function SliderRow({
  label,
  readout,
  children,
}: {
  label: string
  readout: string
  children: React.ReactNode
}) {
  return (
    <div className="flex items-center gap-3">
      <span className="w-20 text-sm text-muted-foreground">{label}</span>
      <div className="flex-1">{children}</div>
      <span className="w-10 text-end font-mono text-sm text-muted-foreground">
        {readout}
      </span>
    </div>
  )
}

"use client"

import * as React from "react"

import { motion, useReducedMotion } from "motion/react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import {
  Item,
  ItemContent,
  ItemDescription,
  ItemTitle,
} from "@/components/ui/item"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"
import {
  voiceById,
  type PersonaGender,
  type PersonaLanguage,
} from "@/lib/mockups/personas-depth-data"
import type { PersonaDraft } from "@/components/mockups/personas-depth/persona-dialog"
import { VoicePicker } from "@/components/mockups/personas-depth/voice-picker"

/**
 * Creating a persona as a run of single decisions — type, click, click,
 * click, Enter — with segment bars up top filling as each step lands.
 * Option steps advance themselves; only typing steps have a Continue.
 * Editing stays in the tabbed dialog; this is the fast path in.
 */

/**
 * The height morph between steps. Faster than a hover-to-expand spring, because
 * this fires on a committed action — you have already picked, and the dialog
 * catching up should feel like it is keeping pace, not performing. Just enough
 * bounce to read as physical; not enough to overshoot a body of text twice.
 */
const STEP_SPRING = {
  type: "spring",
  visualDuration: 0.26,
  bounce: 0.14,
} as const

const STEPS = [
  "name",
  "language",
  "gender",
  "voice",
  "prompt",
  "review",
] as const
type Step = (typeof STEPS)[number]

const LANGUAGE_OPTIONS: { value: PersonaLanguage; hint: string }[] = [
  { value: "Arabic", hint: "العربية" },
  { value: "English", hint: "English" },
  { value: "Urdu", hint: "اردو" },
]

const GENDER_OPTIONS: { value: PersonaGender; hint: string }[] = [
  { value: "Female", hint: "Female voices only" },
  { value: "Male", hint: "Male voices only" },
]

export function PersonaWizard({
  open,
  onOpenChange,
  onSubmit,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSubmit: (draft: PersonaDraft) => void
}) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      {/* 512px, not 672px. One question per step means the widest thing here is
          a two-column voice list and a three-up language row — both of which
          fit. At 2xl a step that asks for a name was a single input spanning
          672px, which reads as a form that lost its other fields. */}
      <DialogContent className="sm:max-w-lg" showCloseButton={false}>
        <WizardBody onSubmit={onSubmit} onClose={() => onOpenChange(false)} />
      </DialogContent>
    </Dialog>
  )
}

function WizardBody({
  onSubmit,
  onClose,
}: {
  onSubmit: (draft: PersonaDraft) => void
  onClose: () => void
}) {
  const [stepIndex, setStepIndex] = React.useState(0)
  const [name, setName] = React.useState("")
  const [language, setLanguage] = React.useState<PersonaLanguage>("Arabic")
  const [gender, setGender] = React.useState<PersonaGender>("Female")
  const [voiceId, setVoiceId] = React.useState("")
  const [prompt, setPrompt] = React.useState("")

  const step: Step = STEPS[stepIndex]
  const voice = voiceById(voiceId)

  function next() {
    setStepIndex((index) => Math.min(index + 1, STEPS.length - 1))
  }

  function back() {
    setStepIndex((index) => Math.max(index - 1, 0))
  }

  /**
   * Lets the picked card paint its selected state before the step flips.
   *
   * 120ms, not 200ms: the hold used to be the whole delay before anything
   * moved, and now it sits in front of a 260ms height spring, so the two
   * stacked to 460ms from click to settled. 120ms is still long enough for the
   * selected border to register and takes a third off the felt latency.
   */
  function pickAndAdvance(apply: () => void) {
    apply()
    window.setTimeout(next, 120)
  }

  function create() {
    onSubmit({ name: name.trim(), language, gender, voiceId, prompt })
    onClose()
  }

  const heading: Record<Step, { title: string; hint: string }> = {
    name: {
      title: "Name the persona",
      hint: "What it's called in lists and scenarios.",
    },
    language: {
      title: "What language does it speak?",
      hint: "One persona speaks one language.",
    },
    gender: {
      title: "Who's speaking?",
      hint: "Only matching voices are offered next.",
    },
    voice: {
      title: "Pick the voice",
      hint: "This is the voice it speaks with on every call.",
    },
    prompt: {
      title: "How should it behave?",
      hint: "Optional — identity, personality, and tone. You can refine this any time.",
    },
    review: {
      title: "Ready to create",
      hint: "Conversation behavior starts from the language defaults — tune it later from Edit.",
    },
  }

  return (
    <div className="flex flex-col gap-4">
      {/* One segment per step; a segment's fill scales in as its step lands. */}
      <div
        className="flex gap-1.5"
        role="progressbar"
        aria-valuemin={1}
        aria-valuemax={STEPS.length}
        aria-valuenow={stepIndex + 1}
        aria-label={`Step ${stepIndex + 1} of ${STEPS.length}`}
      >
        {STEPS.map((segment, index) => (
          <div
            key={segment}
            className="h-1 flex-1 overflow-hidden rounded-full bg-muted"
          >
            <div
              className={cn(
                "h-full w-full origin-left rounded-full bg-primary transition-transform duration-300 ease-out-cubic motion-reduce:transition-none",
                index <= stepIndex ? "scale-x-100" : "scale-x-0",
              )}
            />
          </div>
        ))}
      </div>

      <div className="flex flex-col gap-1">
        <DialogTitle>{heading[step].title}</DialogTitle>
        <DialogDescription>{heading[step].hint}</DialogDescription>
      </div>

      {/* A small floor, not the voice step's full 288px. The tall step caps
          itself (`max-h-72` inside VoicePicker), so the only thing a 288px
          floor bought was a dialog that never resizes — paid for by every short
          step, and the name step is one input sitting in 250px of nothing. The
          steps size to their content now, and StepBody springs the difference
          so the dialog grows instead of snapping. */}
      <StepBody>
        {step === "name" ? (
          <Input
            autoFocus
            value={name}
            onChange={(event) => setName(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter" && name.trim()) {
                event.preventDefault()
                next()
              }
            }}
            placeholder="Aisha — Yelo Support"
            aria-label="Persona name"
          />
        ) : null}

        {step === "language" ? (
          <div className="grid gap-3 md:grid-cols-3">
            {LANGUAGE_OPTIONS.map((option) => (
              <OptionCard
                key={option.value}
                title={option.value}
                hint={option.hint}
                selected={language === option.value}
                onPick={() =>
                  pickAndAdvance(() => {
                    if (option.value !== language) setVoiceId("")
                    setLanguage(option.value)
                  })
                }
              />
            ))}
          </div>
        ) : null}

        {step === "gender" ? (
          <div className="grid gap-3 md:grid-cols-2">
            {GENDER_OPTIONS.map((option) => (
              <OptionCard
                key={option.value}
                title={option.value}
                hint={option.hint}
                selected={gender === option.value}
                onPick={() =>
                  pickAndAdvance(() => {
                    if (option.value !== gender) setVoiceId("")
                    setGender(option.value)
                  })
                }
              />
            ))}
          </div>
        ) : null}

        {step === "voice" ? (
          <VoicePicker
            language={language}
            gender={gender}
            selectedId={voiceId}
            onSelect={(id) => pickAndAdvance(() => setVoiceId(id))}
          />
        ) : null}

        {step === "prompt" ? (
          <Textarea
            autoFocus
            rows={7}
            value={prompt}
            onChange={(event) => setPrompt(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter" && !event.shiftKey) {
                event.preventDefault()
                next()
              }
            }}
            placeholder="Define the agent's identity, personality, and tone. Shift+Enter for a new line."
            aria-label="Persona prompt"
          />
        ) : null}

        {step === "review" ? (
          <div className="flex flex-col gap-3">
            <ReviewRow label="Name" value={name.trim()} />
            <ReviewRow label="Language" value={`${language} · ${gender}`} />
            <ReviewRow label="Voice" value={voice?.name ?? "—"} />
            <ReviewRow
              label="Prompt"
              value={prompt.trim() || "Starts from the language default."}
              muted={!prompt.trim()}
            />
          </div>
        ) : null}
      </StepBody>

      <div className="flex items-center justify-between gap-2">
        {stepIndex > 0 ? (
          <Button variant="ghost" onClick={back}>
            Back
          </Button>
        ) : (
          <span />
        )}

        {step === "name" ? (
          <Button disabled={!name.trim()} onClick={next}>
            Continue
          </Button>
        ) : null}
        {step === "prompt" ? (
          <Button onClick={next}>
            {prompt.trim() ? "Continue" : "Skip for now"}
          </Button>
        ) : null}
        {step === "review" ? (
          <Button onClick={create}>Create persona</Button>
        ) : null}
      </div>
    </div>
  )
}

/**
 * The step body, springing between step heights instead of snapping.
 *
 * A wrapper measuring its child with a ResizeObserver and animating `height` is
 * the one layout animation the house rules allow, and this is the case they
 * describe: a container morphing to fit new content, on an interaction that
 * happens six times per persona rather than constantly. Motion drives it so the
 * spring is interruptible — stepping back before the previous step settles
 * redirects from wherever it got to, which a CSS transition cannot do.
 *
 * `height: auto` until the first measurement, so the first paint is the real
 * height rather than zero.
 *
 * The clip is on only while the height is actually moving. `overflow-hidden`
 * kept permanently is what cuts a focus ring off at the wrapper's edge — the
 * ring is drawn outside the element's box, so a settled step must not clip at
 * all. During the morph it has to, or the taller step's content spills past a
 * container that has not grown to hold it yet.
 */
function StepBody({ children }: { children: React.ReactNode }) {
  const reduce = useReducedMotion()
  const innerRef = React.useRef<HTMLDivElement>(null)
  const [height, setHeight] = React.useState<"auto" | number>("auto")
  const [morphing, setMorphing] = React.useState(false)

  React.useLayoutEffect(() => {
    const inner = innerRef.current
    if (!inner) return

    const observer = new ResizeObserver(([entry]) => {
      setHeight(entry.contentRect.height)
    })
    observer.observe(inner)
    return () => observer.disconnect()
  }, [])

  return (
    <motion.div
      /* No entry animation — the dialog already has its own open transition,
         and a height spring on top of it reads as two things arriving. */
      initial={false}
      animate={{ height }}
      transition={reduce ? { duration: 0 } : STEP_SPRING}
      onAnimationStart={() => setMorphing(true)}
      onAnimationComplete={() => setMorphing(false)}
      className={morphing ? "overflow-hidden" : undefined}
    >
      <div className="flex min-h-32 flex-col gap-4" ref={innerRef}>
        {children}
      </div>
    </motion.div>
  )
}

function OptionCard({
  title,
  hint,
  selected,
  onPick,
}: {
  title: string
  hint: string
  selected: boolean
  onPick: () => void
}) {
  return (
    <Item
      variant="outline"
      asChild
      className={cn(selected && "border-primary bg-primary-tint/40")}
    >
      <button
        type="button"
        aria-pressed={selected}
        onClick={onPick}
        className={cn("w-full text-start", !selected && "hover:bg-muted")}
      >
        <ItemContent>
          <ItemTitle>{title}</ItemTitle>
          <ItemDescription dir="auto">{hint}</ItemDescription>
        </ItemContent>
      </button>
    </Item>
  )
}

function ReviewRow({
  label,
  value,
  muted = false,
}: {
  label: string
  value: string
  muted?: boolean
}) {
  return (
